-- Proposed additive migration 0082: scheduling only, no financial rights.
CREATE TABLE prepaid_renewal_admissions (contract_id TEXT NOT NULL REFERENCES prepaid_contracts(contract_id), ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 1 AND 9007199254740991), anchor_start INTEGER NOT NULL CHECK(typeof(anchor_start)='integer' AND anchor_start>0), starts_at INTEGER NOT NULL CHECK(typeof(starts_at)='integer' AND starts_at>=anchor_start), ends_at INTEGER NOT NULL CHECK(typeof(ends_at)='integer' AND ends_at>starts_at), last_attempt_at INTEGER NOT NULL CHECK(typeof(last_attempt_at)='integer' AND last_attempt_at>=starts_at AND last_attempt_at<ends_at), retry_at INTEGER NOT NULL CHECK(typeof(retry_at)='integer' AND retry_at>=last_attempt_at), lease_token TEXT, lease_until INTEGER NOT NULL, failure_count INTEGER NOT NULL CHECK(typeof(failure_count)='integer' AND failure_count BETWEEN 0 AND 8), last_failure_code TEXT CHECK(last_failure_code IS NULL OR last_failure_code IN ('mandate_rejected','mandate_unavailable')), updated_at INTEGER NOT NULL CHECK(typeof(updated_at)='integer' AND updated_at>=last_attempt_at AND retry_at<=updated_at+3600), PRIMARY KEY(contract_id,ordinal), CHECK((lease_token IS NULL AND lease_until=0) OR (length(lease_token)=36 AND lease_token NOT GLOB '*[^a-f0-9-]*' AND typeof(lease_until)='integer' AND lease_until>last_attempt_at AND lease_until<=last_attempt_at+130)));
--> statement-breakpoint
CREATE INDEX prepaid_renewal_admissions_due ON prepaid_renewal_admissions(retry_at,lease_until,last_attempt_at);
--> statement-breakpoint
CREATE TRIGGER prepaid_renewal_admissions_immutable BEFORE UPDATE ON prepaid_renewal_admissions WHEN NEW.contract_id IS NOT OLD.contract_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.anchor_start IS NOT OLD.anchor_start OR NEW.starts_at IS NOT OLD.starts_at OR NEW.ends_at IS NOT OLD.ends_at OR NEW.last_attempt_at<OLD.last_attempt_at OR NEW.updated_at<OLD.updated_at BEGIN SELECT RAISE(ABORT,'Renewal scheduling identity is immutable'); END;
--> statement-breakpoint
CREATE TRIGGER prepaid_renewal_admissions_no_delete BEFORE DELETE ON prepaid_renewal_admissions BEGIN SELECT RAISE(ABORT,'Renewal scheduling history is retained'); END;
